CREATE   VIEW [synapse_fo].[vwLOGISTICSPOSTALADDRESSBASEENTITY]
AS
SELECT T1.LOCATIONID AS LOCATIONID
	,T1.DESCRIPTION AS DESCRIPTION
	,T1.RECID AS LOCATIONRECID
	,T1.MODIFIEDDATETIME AS MODIFIEDDATETIME
	,T1.MODIFIEDBY AS MODIFIEDBY
	,T1.CREATEDDATETIME AS CREATEDDATETIME
	,T1.RECVERSION AS RECVERSION
	,T1.PARTITION AS PARTITION
	,T1.RECID AS RECID
	,T2.ADDRESS AS ADDRESS
	,T2.APARTMENT_RU AS APARTMENT_RU
	,T2.BUILDING_RU AS BUILDING_RU
	,T2.BUILDINGCOMPLIMENT AS BUILDINGCOMPLIMENT
	,T2.CITY AS CITY
	,T2.COUNTRYREGIONID AS COUNTRYREGIONID
	,T2.COUNTY AS COUNTY
	,T2.DISTRICTNAME AS DISTRICTNAME
	,T2.FLATID_RU AS FLATID_RU
	,T2.HOUSEID_RU AS HOUSEID_RU
	,T2.ISPRIVATE AS ISPRIVATE
	,T2.LATITUDE AS LATITUDE
	,T2.LONGITUDE AS LONGITUDE
	,T2.POSTBOX AS POSTBOX
	,T2.STATE AS STATE
	,T2.STREET AS STREET
	,T2.STREETID_RU AS STREETID_RU
	,T2.STREETNUMBER AS STREETNUMBER
	,T2.TIMEZONE AS TIMEZONE
	,T2.VALIDFROM AS VALIDFROM
	,T2.VALIDTO AS VALIDTO
	,T2.ZIPCODE AS ZIPCODE
	,T2.CITYKANA_JP AS CITYINKANA
	,T2.STREETKANA_JP AS STREETINKANA
	,T2.PRIVATEFORPARTY AS PRIVATEFORPARTY
	,T2.RECID AS ADDRESSRECID
	,T2.ISSIMPLIFIEDADDRESS_RU AS SIMPLIFIEDADDRESS
	,T2.RECVERSION AS RECVERSION#2
	,T2.PARTITION AS PARTITION#2
	,T2.RECID AS RECID#2
	,T3.DUNSNUMBER AS DUNSNUMBER
	,T3.RECVERSION AS RECVERSION#5
	,T3.PARTITION AS PARTITION#5
	,T3.RECID AS RECID#5
	,T4.RECVERSION AS RECVERSION#3
	,T4.PARTITION AS PARTITION#3
	,T4.RECID AS RECID#3
	,T5.PARTITION AS PARTITION#4
	,T5.RECID AS RECID#4
	,(CAST((T4.ISOCODE) AS NVARCHAR(2))) AS COUNTRYREGIONISOCODE
	,(CAST((0) AS INT)) AS RESOLVEDUPLICATEADDRESS
	,(
		CAST((
				CASE 
					WHEN CHARINDEX('%1', T2.ADDRESS) > 0
						THEN REPLACE(T2.ADDRESS, '%1', T5.SHORTNAME)
					ELSE T2.ADDRESS
					END
				) AS NVARCHAR(250))
		) AS FORMATTEDDELIVERYADDRESS
FROM synapse_fo.LOGISTICSLOCATION T1
CROSS JOIN synapse_fo.LOGISTICSPOSTALADDRESS T2
LEFT OUTER JOIN synapse_fo.DIRDUNSNUMBER T3 ON (
		(T1.DUNSNUMBERRECID = T3.RECID)
		AND (T1.PARTITION = T3.PARTITION)
		)
LEFT OUTER JOIN synapse_fo.LOGISTICSADDRESSCOUNTRYREGION T4 ON (
		(T2.COUNTRYREGIONID = T4.COUNTRYREGIONID)
		AND (T2.PARTITION = T4.PARTITION)
		)
LEFT OUTER JOIN synapse_fo.vwLOGISTICSADDRESSCOUNTRYREGTRANSLFILTERED T5 ON (
		(T2.COUNTRYREGIONID = T5.COUNTRYREGIONID)
		AND (T2.PARTITION = T5.PARTITION)
		)
WHERE (
		(T1.ISPOSTALADDRESS = 1)
		AND (
			(T1.RECID = T2.LOCATION)
			AND (T1.PARTITION = T2.PARTITION)
			)
		)
